# filename: fix-argocd-cache.ps1
# Code Generated by Sidekick is for learning and experimentation purposes only.

Write-Host "==================================="
Write-Host "Fixing ArgoCD Cache Issue" -ForegroundColor Yellow
Write-Host "==================================="

Write-Host "`n1️⃣  Deleting monitoring application..." -ForegroundColor Cyan
kubectl delete application monitoring -n argocd --wait=true

Write-Host "`n2️⃣  Clearing ArgoCD repo cache..." -ForegroundColor Cyan
# Get the repo server pod
$repoServerPod = kubectl get pods -n argocd -l app.kubernetes.io/name=argocd-repo-server -o jsonpath='{.items[0].metadata.name}'

Write-Host "Repo server pod: $repoServerPod" -ForegroundColor Gray

# Clear the cache
kubectl exec -n argocd $repoServerPod -- sh -c "rm -rf /tmp/*"

Write-Host "✅ Cache cleared" -ForegroundColor Green

Write-Host "`n3️⃣  Restarting repo server..." -ForegroundColor Cyan
kubectl rollout restart deployment argocd-repo-server -n argocd
kubectl rollout status deployment argocd-repo-server -n argocd

Write-Host "`n4️⃣  Waiting for repo server to be ready..." -ForegroundColor Yellow
Start-Sleep -Seconds 10

Write-Host "`n5️⃣  Recreating monitoring application..." -ForegroundColor Cyan

@"
apiVersion: argoproj.io/v1alpha1
kind: Application
metadata:
  name: monitoring
  namespace: argocd
spec:
  project: default
  source:
    repoURL: https://github.com/Sandeshsanthu/system-design-practical.git
    targetRevision: HEAD
    path: URl-Shortner/deployment/monitoring
    directory:
      recurse: true
      exclude: '*.json'  # Exclude all JSON files
  destination:
    server: https://kubernetes.default.svc
    namespace: monitoring
  syncPolicy:
    automated:
      prune: true
      selfHeal: true
    syncOptions:
      - CreateNamespace=true
"@ | kubectl apply -f -

Write-Host "✅ Application recreated with JSON files excluded" -ForegroundColor Green

Write-Host "`n6️⃣  Checking application status..." -ForegroundColor Cyan
Start-Sleep -Seconds 5
kubectl get application monitoring -n argocd

Write-Host "`n==================================="
Write-Host "✅ Done!" -ForegroundColor Green
Write-Host "==================================="
Write-Host "`nMonitor the sync:" -ForegroundColor Yellow
Write-Host "  kubectl get application monitoring -n argocd -w"
